          type="email"
          name="email"
          label="Email"
          placeholder="you@example.com"
          value={email}
          onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
            setEmail(event.target.value)
          }
          required
          className="jx-field"
        />
        <Button type="submit" variant="primary" className="jx-button">
          Подписаться
        </Button>
      </form>

